create extension if not exists pgcrypto;
create extension if not exists pg_trgm;
create type public.member_role as enum ('member','moderator','admin');
create type public.post_kind as enum ('discussion','question','resource','announcement','showcase');
create type public.content_status as enum ('published','removed','hidden');
create type public.report_reason as enum ('spam','harassment','inappropriate','misleading','copyright','other');
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,username text not null,username_key text generated always as (lower(username)) stored unique,display_name text not null default '',avatar_file_id text,bio text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint profiles_username_check check(username ~ '^[A-Za-z0-9_]{3,24}$'),constraint profiles_bio_check check(char_length(bio)<=500));
create table public.communities(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,description text not null default '',icon text,banner_file_id text,creator_id uuid references public.profiles(user_id) on delete set null,rules jsonb not null default '[]'::jsonb,member_count integer not null default 0 check(member_count>=0),created_at timestamptz not null default now());
create table public.community_members(community_id uuid references public.communities(id) on delete cascade,user_id uuid default auth.uid() references public.profiles(user_id) on delete cascade,role public.member_role not null default 'member',joined_at timestamptz not null default now(),primary key(community_id,user_id));
create table public.posts(id uuid primary key default gen_random_uuid(),community_id uuid not null references public.communities(id) on delete restrict,author_id uuid not null default auth.uid() references public.profiles(user_id) on delete restrict,title text not null,content text not null default '',post_type public.post_kind not null default 'discussion',status public.content_status not null default 'published',vote_score integer not null default 0,comment_count integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint post_title_check check(char_length(title) between 4 and 180),constraint post_content_check check(char_length(content)<=20000));
create table public.files(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(user_id) on delete restrict,community_id uuid references public.communities(id) on delete restrict,storage_provider text not null check(storage_provider in ('appwrite','r2')),storage_file_id text not null,storage_bucket_id text not null,original_filename text not null,mime_type text not null,file_size bigint not null check(file_size>0 and file_size<=4194304),category text not null default 'attachment',description text not null default '',sha256 text,visibility text not null default 'community' check(visibility in ('community','private')),status public.content_status not null default 'published',created_at timestamptz not null default now(),unique(storage_provider,storage_bucket_id,storage_file_id));
create table public.post_attachments(post_id uuid references public.posts(id) on delete cascade,file_id uuid references public.files(id) on delete restrict,position smallint not null default 0,primary key(post_id,file_id));
create table public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,author_id uuid not null default auth.uid() references public.profiles(user_id) on delete restrict,parent_comment_id uuid references public.comments(id) on delete cascade,content text not null,status public.content_status not null default 'published',vote_score integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(char_length(content) between 1 and 10000));
create table public.votes(user_id uuid references public.profiles(user_id) on delete cascade,post_id uuid references public.posts(id) on delete cascade,comment_id uuid references public.comments(id) on delete cascade,value smallint not null check(value in (-1,1)),created_at timestamptz not null default now(),check((post_id is not null)::int+(comment_id is not null)::int=1),unique(user_id,post_id),unique(user_id,comment_id));
create table public.saved_posts(user_id uuid default auth.uid() references public.profiles(user_id) on delete cascade,post_id uuid references public.posts(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,post_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(user_id) on delete cascade,actor_id uuid references public.profiles(user_id) on delete set null,kind text not null check(kind in ('comment','reply','announcement','moderation')),post_id uuid references public.posts(id) on delete cascade,comment_id uuid references public.comments(id) on delete cascade,message text not null default '',read_at timestamptz,created_at timestamptz not null default now());
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(user_id) on delete restrict,post_id uuid references public.posts(id) on delete cascade,comment_id uuid references public.comments(id) on delete cascade,file_id uuid references public.files(id) on delete cascade,reported_user_id uuid references public.profiles(user_id) on delete cascade,reason public.report_reason not null,details text not null default '',state text not null default 'open' check(state in ('open','reviewing','resolved','dismissed')),reviewer_id uuid references public.profiles(user_id) on delete set null,created_at timestamptz not null default now(),resolved_at timestamptz,check((post_id is not null)::int+(comment_id is not null)::int+(file_id is not null)::int+(reported_user_id is not null)::int=1));
